import numpy as np


def bce(pred, target):
    p = np.clip(pred, 1e-7, 1 - 1e-7)
    return -np.mean(target * np.log(p) + (1 - target) * np.log(1 - p))


def transposed_conv_output_size(n, kernel, stride=1, padding=0):
    return (n - 1) * stride - 2 * padding + kernel


def smooth_real_labels(n, smoothing=0.1):
    return np.full(n, 1.0 - smoothing)


def discriminator_loss(d_real, d_fake, smoothing=0.1):
    real_labels = smooth_real_labels(len(d_real), smoothing)
    return bce(d_real, real_labels) + bce(d_fake, np.zeros(len(d_fake)))


def to_pixels(x):
    return np.clip(np.round((x + 1) * 127.5), 0, 255).astype(np.uint8)


size = 4
print("generator upsampling:", size, end="")
for _ in range(3):
    size = transposed_conv_output_size(size, kernel=4, stride=2, padding=1)
    print(" ->", size, end="")
print()
print("smoothed real labels:", smooth_real_labels(3))
d_real, d_fake = np.array([0.9, 0.85, 0.95]), np.array([0.1, 0.2, 0.05])
loss = discriminator_loss(d_real, d_fake)
print("D loss with label smoothing:", None if loss is None else round(float(loss), 4))
print("pixels:", to_pixels(np.array([-1.0, 0.0, 1.0])))
